def maxGold(grid):
    rows, cols = len(grid), len(grid[0])

    def walk(y, x):
        gold = grid[y][x]
        grid[y][x] = 0
        best = 0
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] > 0:
                best = max(best, walk(ny, nx))
        grid[y][x] = gold
        return gold + best

    answer = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] > 0:
                answer = max(answer, walk(r, c))
    return answer
